#!/usr/bin/env node
// FYP.STUDIO — Panel Admin (Parte 2)
// Ejecutar desde la raíz del proyecto: node setup_admin.js
const fs = require('fs')
const path = require('path')
const files = {}

files["app/admin/layout.tsx"] = "// app/admin/layout.tsx\nimport { redirect } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/server'\nimport AdminSidebar from '@/components/admin/AdminSidebar'\n\nexport default async function AdminLayout({ children }: { children: React.ReactNode }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('*, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  const needsOnboarding = !profile || !profile.business_id\n  const business = profile?.business ?? null\n\n  return (\n    <div className=\"flex h-screen bg-[#f9f9f8] overflow-hidden\">\n      {!needsOnboarding && (\n        <AdminSidebar business={business} userEmail={user.email ?? ''} />\n      )}\n      <main className={`flex-1 overflow-y-auto ${needsOnboarding ? 'w-full' : ''}`}>\n        {business?.subscription_status === 'suspended' && (\n          <div className=\"bg-red-500 text-white text-xs text-center py-2 px-4 font-medium\">\n            ⚠️ Suscripción suspendida — contactá soporte para reactivar\n          </div>\n        )}\n        <div className={needsOnboarding ? '' : 'p-6 lg:p-8 max-w-6xl mx-auto'}>\n          {children}\n        </div>\n      </main>\n    </div>\n  )\n}\n"

files["app/admin/page.tsx"] = "// app/admin/page.tsx\nimport { redirect } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/server'\nimport { formatPrice, orderStatusLabel, orderStatusColor, formatDate } from '@/lib/utils'\nimport Link from 'next/link'\nimport { ShoppingBag, TrendingUp, Users, Package, ArrowRight, Clock } from 'lucide-react'\nimport type { Order } from '@/types'\n\nexport const metadata = { title: 'Dashboard' }\n\nexport default async function AdminDashboard() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(name, currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  // Sin negocio → onboarding\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const businessId = profile.business_id\n  const biz = profile.business as { name: string; currency: string } | null\n  const currency = biz?.currency ?? 'UYU'\n\n  // Queries en paralelo\n  const [ordersRes, productsRes, customersRes] = await Promise.all([\n    supabase\n      .from('orders')\n      .select('id, order_number, status, confirmed_sale, total, customer_name, customer_phone, created_at')\n      .eq('business_id', businessId)\n      .order('created_at', { ascending: false })\n      .limit(100),\n    supabase\n      .from('products')\n      .select('id', { count: 'exact', head: true })\n      .eq('business_id', businessId)\n      .eq('active', true),\n    supabase\n      .from('customers')\n      .select('id', { count: 'exact', head: true })\n      .eq('business_id', businessId),\n  ])\n\n  const orders = (ordersRes.data ?? []) as Order[]\n  const totalProducts = productsRes.count ?? 0\n  const totalCustomers = customersRes.count ?? 0\n\n  const pendingOrders = orders.filter(o => o.status === 'pending').length\n  const confirmedOrders = orders.filter(o =>\n    ['confirmed', 'preparing', 'ready', 'shipped', 'delivered'].includes(o.status)\n  ).length\n  const totalRevenue = orders\n    .filter(o => o.confirmed_sale)\n    .reduce((acc, o) => acc + (o.total ?? 0), 0)\n\n  const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0)\n  const todayRevenue = orders\n    .filter(o => o.confirmed_sale && new Date(o.created_at) >= todayStart)\n    .reduce((acc, o) => acc + (o.total ?? 0), 0)\n\n  const recentOrders = orders.slice(0, 6)\n\n  return (\n    <div className=\"space-y-8 animate-fade-in\">\n      {/* Header */}\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Dashboard</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">\n            {new Date().toLocaleDateString('es-UY', { weekday: 'long', day: 'numeric', month: 'long' })}\n          </p>\n        </div>\n        {todayRevenue > 0 && (\n          <div className=\"hidden sm:flex flex-col items-end\">\n            <span className=\"text-xs text-gray-400\">Hoy</span>\n            <span className=\"text-lg font-semibold text-green-600\">{formatPrice(todayRevenue, currency)}</span>\n          </div>\n        )}\n      </div>\n\n      {/* Stats */}\n      <div className=\"grid grid-cols-2 xl:grid-cols-4 gap-4\">\n        {[\n          {\n            label: 'Pendientes',\n            value: pendingOrders,\n            icon: Clock,\n            href: '/admin/orders?status=pending',\n            accent: pendingOrders > 0,\n            sub: 'sin confirmar',\n          },\n          {\n            label: 'Confirmados',\n            value: confirmedOrders,\n            icon: ShoppingBag,\n            href: '/admin/orders',\n            sub: 'en curso',\n          },\n          {\n            label: 'Ingresos totales',\n            value: formatPrice(totalRevenue, currency),\n            icon: TrendingUp,\n            href: '/admin/orders',\n            sub: 'ventas reales',\n          },\n          {\n            label: 'Productos activos',\n            value: totalProducts,\n            icon: Package,\n            href: '/admin/products',\n            sub: `${totalCustomers} clientes`,\n          },\n        ].map(({ label, value, icon: Icon, href, accent, sub }) => (\n          <Link key={label} href={href} className=\"group\">\n            <div className={`rounded-2xl border p-5 bg-white transition-all hover:shadow-sm\n                            ${accent ? 'border-orange-200 bg-orange-50/60' : 'border-gray-100'}`}>\n              <div className=\"flex items-start justify-between mb-4\">\n                <div className={`flex h-8 w-8 items-center justify-center rounded-lg\n                                ${accent ? 'bg-orange-100' : 'bg-gray-100'}`}>\n                  <Icon size={15} className={accent ? 'text-orange-600' : 'text-gray-500'} />\n                </div>\n                <ArrowRight size={14} className=\"text-gray-300 group-hover:text-gray-500 transition-colors mt-1\" />\n              </div>\n              <p className={`text-2xl font-semibold tracking-tight mb-1\n                            ${accent ? 'text-orange-600' : 'text-gray-900'}`}>\n                {value}\n              </p>\n              <p className=\"text-xs text-gray-400\">{label}</p>\n              <p className=\"text-xs text-gray-300 mt-0.5\">{sub}</p>\n            </div>\n          </Link>\n        ))}\n      </div>\n\n      {/* Pedidos recientes */}\n      <div>\n        <div className=\"flex items-center justify-between mb-4\">\n          <h2 className=\"font-semibold text-gray-900\">Pedidos recientes</h2>\n          <Link href=\"/admin/orders\" className=\"text-xs text-gray-400 hover:text-gray-700 transition-colors flex items-center gap-1\">\n            Ver todos <ArrowRight size={12} />\n          </Link>\n        </div>\n\n        {recentOrders.length === 0 ? (\n          <div className=\"rounded-2xl border-2 border-dashed border-gray-200 p-14 text-center\">\n            <ShoppingBag size={28} className=\"mx-auto text-gray-200 mb-3\" />\n            <p className=\"text-sm font-medium text-gray-400\">Sin pedidos todavía</p>\n            <p className=\"text-xs text-gray-300 mt-1\">Compartí el link de tu tienda para empezar</p>\n          </div>\n        ) : (\n          <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden\">\n            {/* Tabla desktop */}\n            <div className=\"hidden sm:block overflow-x-auto\">\n              <table className=\"w-full\">\n                <thead>\n                  <tr className=\"border-b border-gray-100\">\n                    {['Pedido', 'Cliente', 'Total', 'Estado', 'Fecha'].map(h => (\n                      <th key={h} className=\"text-left text-xs font-medium text-gray-400 px-5 py-3.5\">{h}</th>\n                    ))}\n                  </tr>\n                </thead>\n                <tbody>\n                  {recentOrders.map(order => (\n                    <tr key={order.id} className=\"border-b border-gray-50 last:border-0 hover:bg-gray-50/50 transition-colors\">\n                      <td className=\"px-5 py-4 text-sm font-mono text-gray-400\">\n                        #{String(order.order_number).padStart(4, '0')}\n                      </td>\n                      <td className=\"px-5 py-4\">\n                        <p className=\"text-sm font-medium text-gray-900\">{order.customer_name}</p>\n                        <p className=\"text-xs text-gray-400\">{order.customer_phone}</p>\n                      </td>\n                      <td className=\"px-5 py-4 text-sm font-semibold text-gray-900\">\n                        {formatPrice(order.total, currency)}\n                      </td>\n                      <td className=\"px-5 py-4\">\n                        <span className={`badge ${orderStatusColor(order.status)}`}>\n                          {orderStatusLabel(order.status)}\n                        </span>\n                      </td>\n                      <td className=\"px-5 py-4 text-xs text-gray-400\">{formatDate(order.created_at)}</td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n\n            {/* Lista mobile */}\n            <div className=\"sm:hidden divide-y divide-gray-50\">\n              {recentOrders.map(order => (\n                <Link key={order.id} href={`/admin/orders/${order.id}`}\n                  className=\"flex items-center justify-between px-4 py-3.5 hover:bg-gray-50/50\">\n                  <div>\n                    <p className=\"text-sm font-medium text-gray-900\">{order.customer_name}</p>\n                    <p className=\"text-xs text-gray-400 mt-0.5\">#{String(order.order_number).padStart(4, '0')}</p>\n                  </div>\n                  <div className=\"text-right\">\n                    <p className=\"text-sm font-semibold text-gray-900\">{formatPrice(order.total, currency)}</p>\n                    <span className={`badge ${orderStatusColor(order.status)} mt-1`}>\n                      {orderStatusLabel(order.status)}\n                    </span>\n                  </div>\n                </Link>\n              ))}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* Quick actions */}\n      <div className=\"grid grid-cols-2 gap-3\">\n        <Link href=\"/admin/products/new\"\n          className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-4\n                     hover:border-gray-300 hover:shadow-sm transition-all group\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-gray-100 group-hover:bg-gray-200 transition-colors\">\n            <Package size={16} className=\"text-gray-600\" />\n          </div>\n          <div>\n            <p className=\"text-sm font-medium text-gray-900\">Nuevo producto</p>\n            <p className=\"text-xs text-gray-400\">Agregar al catálogo</p>\n          </div>\n        </Link>\n        <Link href=\"/admin/orders\"\n          className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-4\n                     hover:border-gray-300 hover:shadow-sm transition-all group\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-gray-100 group-hover:bg-gray-200 transition-colors\">\n            <ShoppingBag size={16} className=\"text-gray-600\" />\n          </div>\n          <div>\n            <p className=\"text-sm font-medium text-gray-900\">Ver pedidos</p>\n            <p className=\"text-xs text-gray-400\">Gestionar estados</p>\n          </div>\n        </Link>\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/onboarding/page.tsx"] = "// app/admin/onboarding/page.tsx\n// Se muestra cuando el usuario logueado no tiene negocio vinculado\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { slugify } from '@/lib/utils'\nimport { Store, Zap } from 'lucide-react'\n\nexport default function OnboardingPage() {\n  const router = useRouter()\n  const supabase = createClient()\n\n  const [loading, setLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [name, setName] = useState('')\n  const [whatsapp, setWhatsapp] = useState('')\n  const [currency, setCurrency] = useState('UYU')\n\n  async function createDemo() {\n    setLoading(true)\n    setError(null)\n    try {\n      const { data: { user } } = await supabase.auth.getUser()\n      if (!user) throw new Error('No autenticado')\n\n      // Crear negocio demo\n      const slug = 'demo-' + Math.random().toString(36).slice(2, 7)\n      const { data: biz, error: bizErr } = await supabase\n        .from('businesses')\n        .insert({\n          name: 'Mi Comercio Demo',\n          slug,\n          currency: 'UYU',\n          plan: 'pro',\n          active: true,\n          subscription_status: 'trial',\n        })\n        .select('id')\n        .single()\n\n      if (bizErr) throw bizErr\n\n      const { error: profErr } = await supabase\n        .from('profiles')\n        .upsert({ user_id: user.id, business_id: biz.id, role: 'owner' })\n\n      if (profErr) throw profErr\n      router.push('/admin')\n      router.refresh()\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  async function createCustom(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim()) return\n    setLoading(true)\n    setError(null)\n    try {\n      const { data: { user } } = await supabase.auth.getUser()\n      if (!user) throw new Error('No autenticado')\n\n      let slug = slugify(name)\n      // Verificar slug único\n      const { data: existing } = await supabase\n        .from('businesses')\n        .select('id')\n        .eq('slug', slug)\n        .maybeSingle()\n      if (existing) slug = slug + '-' + Math.random().toString(36).slice(2, 5)\n\n      const { data: biz, error: bizErr } = await supabase\n        .from('businesses')\n        .insert({\n          name: name.trim(),\n          slug,\n          whatsapp: whatsapp.trim() || null,\n          currency,\n          plan: 'pro',\n          active: true,\n          subscription_status: 'trial',\n        })\n        .select('id')\n        .single()\n\n      if (bizErr) throw bizErr\n\n      const { error: profErr } = await supabase\n        .from('profiles')\n        .upsert({ user_id: user.id, business_id: biz.id, role: 'owner' })\n\n      if (profErr) throw profErr\n      router.push('/admin')\n      router.refresh()\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  return (\n    <div className=\"min-h-screen bg-[#f9f9f8] flex items-center justify-center p-4\">\n      <div className=\"w-full max-w-lg\">\n        <div className=\"text-center mb-10\">\n          <span className=\"font-semibold text-xl tracking-tight\">FYP.STUDIO</span>\n          <h1 className=\"text-2xl font-semibold mt-6 mb-2 tracking-tight\">Configurá tu comercio</h1>\n          <p className=\"text-gray-500 text-sm\">Tu cuenta está lista. Ahora vinculá o creá tu negocio.</p>\n        </div>\n\n        <div className=\"grid grid-cols-1 gap-4 mb-6\">\n          {/* Opción rápida: demo */}\n          <button\n            onClick={createDemo}\n            disabled={loading}\n            className=\"group relative flex items-start gap-4 rounded-2xl border-2 border-dashed border-gray-200\n                       bg-white p-5 text-left hover:border-black transition-all duration-150\n                       disabled:opacity-50 disabled:cursor-not-allowed\"\n          >\n            <div className=\"shrink-0 flex h-10 w-10 items-center justify-center rounded-xl bg-black text-white\">\n              <Zap size={18} />\n            </div>\n            <div>\n              <p className=\"font-semibold text-gray-900 mb-0.5\">Empezar con demo</p>\n              <p className=\"text-sm text-gray-500\">Crea un negocio de prueba al instante. Podés personalizarlo después.</p>\n            </div>\n          </button>\n        </div>\n\n        {/* Formulario: negocio propio */}\n        <div className=\"bg-white rounded-2xl border border-gray-200 p-6\">\n          <div className=\"flex items-center gap-3 mb-5\">\n            <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-gray-100\">\n              <Store size={16} className=\"text-gray-600\" />\n            </div>\n            <div>\n              <p className=\"font-semibold text-sm text-gray-900\">Crear mi comercio</p>\n              <p className=\"text-xs text-gray-400\">Ingresá los datos de tu negocio</p>\n            </div>\n          </div>\n\n          <form onSubmit={createCustom} className=\"space-y-4\">\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">\n                Nombre del negocio <span className=\"text-red-400\">*</span>\n              </label>\n              <input\n                type=\"text\"\n                required\n                value={name}\n                onChange={e => setName(e.target.value)}\n                placeholder=\"Ej: Burger House, Cafetería Volfer...\"\n                className=\"input-base\"\n              />\n            </div>\n\n            <div className=\"grid grid-cols-2 gap-3\">\n              <div>\n                <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">WhatsApp</label>\n                <input\n                  type=\"text\"\n                  value={whatsapp}\n                  onChange={e => setWhatsapp(e.target.value)}\n                  placeholder=\"59899123456\"\n                  className=\"input-base\"\n                />\n              </div>\n              <div>\n                <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">Moneda</label>\n                <select value={currency} onChange={e => setCurrency(e.target.value)} className=\"input-base\">\n                  <option value=\"UYU\">UYU — Peso uruguayo</option>\n                  <option value=\"ARS\">ARS — Peso argentino</option>\n                  <option value=\"CLP\">CLP — Peso chileno</option>\n                  <option value=\"COP\">COP — Peso colombiano</option>\n                  <option value=\"MXN\">MXN — Peso mexicano</option>\n                  <option value=\"USD\">USD — Dólar</option>\n                  <option value=\"BRL\">BRL — Real brasileño</option>\n                </select>\n              </div>\n            </div>\n\n            {error && (\n              <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n            )}\n\n            <button\n              type=\"submit\"\n              disabled={loading || !name.trim()}\n              className=\"w-full rounded-xl bg-black py-3 text-sm font-medium text-white\n                         hover:bg-gray-800 transition-colors disabled:opacity-40 active:scale-[0.98]\"\n            >\n              {loading ? 'Creando...' : 'Crear negocio y entrar al panel →'}\n            </button>\n          </form>\n        </div>\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/products/page.tsx"] = "// app/admin/products/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice } from '@/lib/utils'\nimport Link from 'next/link'\nimport { Plus, Package, MoreHorizontal } from 'lucide-react'\nimport ProductActions from './ProductActions'\nimport type { Product } from '@/types'\n\nexport const metadata = { title: 'Productos' }\n\nexport default async function ProductsPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: products } = await supabase\n    .from('products')\n    .select('*, category:categories(name)')\n    .eq('business_id', profile.business_id)\n    .order('created_at', { ascending: false })\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n  const list = (products ?? []) as (Product & { category?: { name: string } | null })[]\n  const active = list.filter(p => p.active).length\n  const inactive = list.filter(p => !p.active).length\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      {/* Header */}\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Productos</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">{active} activos · {inactive} inactivos</p>\n        </div>\n        <Link href=\"/admin/products/new\"\n          className=\"flex items-center gap-2 rounded-xl bg-black px-4 py-2.5 text-sm font-medium\n                     text-white hover:bg-gray-800 transition-colors active:scale-[0.98]\">\n          <Plus size={15} /> Nuevo producto\n        </Link>\n      </div>\n\n      {/* Lista */}\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 p-16 text-center\">\n          <Package size={32} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">Sin productos todavía</p>\n          <p className=\"text-xs text-gray-300 mt-1 mb-5\">Creá tu primer producto para empezar</p>\n          <Link href=\"/admin/products/new\"\n            className=\"inline-flex items-center gap-2 rounded-xl bg-black px-5 py-2.5 text-sm font-medium text-white hover:bg-gray-800\">\n            <Plus size={15} /> Crear producto\n          </Link>\n        </div>\n      ) : (\n        <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden\">\n          {/* Desktop */}\n          <div className=\"hidden sm:block\">\n            <table className=\"w-full\">\n              <thead>\n                <tr className=\"border-b border-gray-100\">\n                  {['Producto', 'Categoría', 'Precio', 'Estado', ''].map(h => (\n                    <th key={h} className=\"text-left text-xs font-medium text-gray-400 px-5 py-3.5\">{h}</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                {list.map(product => (\n                  <tr key={product.id} className=\"border-b border-gray-50 last:border-0 hover:bg-gray-50/40 transition-colors\">\n                    <td className=\"px-5 py-4\">\n                      <div className=\"flex items-center gap-3\">\n                        {product.images?.[0] ? (\n                          <img src={product.images[0]} alt={product.name}\n                            className=\"h-10 w-10 rounded-xl object-cover ring-1 ring-gray-100 shrink-0\" />\n                        ) : (\n                          <div className=\"h-10 w-10 rounded-xl bg-gray-100 flex items-center justify-center shrink-0\">\n                            <Package size={16} className=\"text-gray-300\" />\n                          </div>\n                        )}\n                        <div>\n                          <p className=\"text-sm font-medium text-gray-900\">{product.name}</p>\n                          {product.featured && (\n                            <span className=\"text-[10px] text-amber-600 font-medium\">★ Destacado</span>\n                          )}\n                        </div>\n                      </div>\n                    </td>\n                    <td className=\"px-5 py-4 text-sm text-gray-400\">\n                      {product.category?.name ?? <span className=\"text-gray-200\">—</span>}\n                    </td>\n                    <td className=\"px-5 py-4 text-sm font-semibold text-gray-900\">\n                      {formatPrice(product.price, currency)}\n                    </td>\n                    <td className=\"px-5 py-4\">\n                      <span className={`badge ${product.active\n                        ? 'bg-green-50 text-green-700'\n                        : 'bg-gray-100 text-gray-400'}`}>\n                        {product.active ? 'Activo' : 'Inactivo'}\n                      </span>\n                    </td>\n                    <td className=\"px-5 py-4 text-right\">\n                      <ProductActions productId={product.id} isActive={product.active} />\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n\n          {/* Mobile */}\n          <div className=\"sm:hidden divide-y divide-gray-50\">\n            {list.map(product => (\n              <div key={product.id} className=\"flex items-center gap-3 px-4 py-3.5\">\n                {product.images?.[0] ? (\n                  <img src={product.images[0]} alt={product.name}\n                    className=\"h-11 w-11 rounded-xl object-cover ring-1 ring-gray-100 shrink-0\" />\n                ) : (\n                  <div className=\"h-11 w-11 rounded-xl bg-gray-100 flex items-center justify-center shrink-0\">\n                    <Package size={16} className=\"text-gray-300\" />\n                  </div>\n                )}\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-medium text-gray-900 truncate\">{product.name}</p>\n                  <p className=\"text-xs text-gray-400\">{formatPrice(product.price, currency)}</p>\n                </div>\n                <ProductActions productId={product.id} isActive={product.active} />\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/products/ProductActions.tsx"] = "// app/admin/products/ProductActions.tsx\n// Client component — botones de acción por producto\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport Link from 'next/link'\nimport { Pencil, Eye, EyeOff, MoreHorizontal } from 'lucide-react'\n\nexport default function ProductActions({ productId, isActive }: { productId: string; isActive: boolean }) {\n  const router = useRouter()\n  const supabase = createClient()\n  const [open, setOpen] = useState(false)\n  const [loading, setLoading] = useState(false)\n\n  async function toggle() {\n    setLoading(true)\n    setOpen(false)\n    await supabase.from('products').update({ active: !isActive }).eq('id', productId)\n    router.refresh()\n    setLoading(false)\n  }\n\n  return (\n    <div className=\"relative\">\n      <button\n        onClick={() => setOpen(o => !o)}\n        disabled={loading}\n        className=\"flex h-8 w-8 items-center justify-center rounded-lg text-gray-400\n                   hover:bg-gray-100 hover:text-gray-700 transition-colors disabled:opacity-40\"\n      >\n        <MoreHorizontal size={15} />\n      </button>\n\n      {open && (\n        <>\n          <div className=\"fixed inset-0 z-10\" onClick={() => setOpen(false)} />\n          <div className=\"absolute right-0 top-9 z-20 w-40 rounded-xl border border-gray-200\n                          bg-white py-1 shadow-lg\">\n            <Link href={`/admin/products/${productId}/edit`}\n              className=\"flex items-center gap-2.5 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50\">\n              <Pencil size={13} /> Editar\n            </Link>\n            <button onClick={toggle}\n              className=\"w-full flex items-center gap-2.5 px-3 py-2 text-sm hover:bg-gray-50\n                         text-gray-700\">\n              {isActive ? <EyeOff size={13} /> : <Eye size={13} />}\n              {isActive ? 'Desactivar' : 'Activar'}\n            </button>\n          </div>\n        </>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/products/ProductForm.tsx"] = "// app/admin/products/ProductForm.tsx\n// Formulario compartido entre /new y /[id]/edit\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { slugify } from '@/lib/utils'\nimport { Upload, X, Loader2 } from 'lucide-react'\nimport type { Product, Category } from '@/types'\n\ninterface Props {\n  businessId: string\n  categories: Category[]\n  product?: Product           // si existe → modo edición\n}\n\nexport default function ProductForm({ businessId, categories, product }: Props) {\n  const router = useRouter()\n  const supabase = createClient()\n\n  const [loading, setLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [uploadingImg, setUploadingImg] = useState(false)\n\n  const [name, setName] = useState(product?.name ?? '')\n  const [description, setDescription] = useState(product?.description ?? '')\n  const [price, setPrice] = useState(product?.price?.toString() ?? '')\n  const [categoryId, setCategoryId] = useState(product?.category_id ?? '')\n  const [featured, setFeatured] = useState(product?.featured ?? false)\n  const [active, setActive] = useState(product?.active ?? true)\n  const [stock, setStock] = useState(product?.stock?.toString() ?? '')\n  const [images, setImages] = useState<string[]>(product?.images ?? [])\n  const [tags, setTags] = useState(product?.tags?.join(', ') ?? '')\n\n  async function uploadImage(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0]\n    if (!file) return\n    setUploadingImg(true)\n    const ext = file.name.split('.').pop()\n    const path = `${businessId}/${Date.now()}.${ext}`\n    const { error, data } = await supabase.storage\n      .from('product-images')\n      .upload(path, file, { upsert: true })\n    if (!error && data) {\n      const { data: url } = supabase.storage.from('product-images').getPublicUrl(data.path)\n      setImages(prev => [...prev, url.publicUrl])\n    }\n    setUploadingImg(false)\n    e.target.value = ''\n  }\n\n  function removeImage(url: string) {\n    setImages(prev => prev.filter(i => i !== url))\n  }\n\n  async function handleSubmit(e: React.FormEvent) {\n    e.preventDefault()\n    if (!name.trim() || !price) return\n    setLoading(true)\n    setError(null)\n\n    try {\n      const slug = product?.slug ?? slugify(name) + '-' + Math.random().toString(36).slice(2, 5)\n      const tagsArr = tags.split(',').map(t => t.trim()).filter(Boolean)\n      const payload = {\n        business_id: businessId,\n        name: name.trim(),\n        slug,\n        description: description.trim() || null,\n        price: parseFloat(price),\n        category_id: categoryId || null,\n        featured,\n        active,\n        stock: stock ? parseInt(stock) : null,\n        images,\n        tags: tagsArr,\n      }\n\n      if (product) {\n        const { error } = await supabase.from('products').update(payload).eq('id', product.id)\n        if (error) throw error\n      } else {\n        const { error } = await supabase.from('products').insert(payload)\n        if (error) throw error\n      }\n\n      router.push('/admin/products')\n      router.refresh()\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error al guardar')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  return (\n    <form onSubmit={handleSubmit} className=\"space-y-6 max-w-2xl\">\n\n      {/* Nombre */}\n      <div>\n        <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">\n          Nombre <span className=\"text-red-400\">*</span>\n        </label>\n        <input type=\"text\" required value={name} onChange={e => setName(e.target.value)}\n          placeholder=\"Ej: Hamburguesa doble cheddar\" className=\"input-base\" />\n      </div>\n\n      {/* Descripción */}\n      <div>\n        <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">Descripción</label>\n        <textarea value={description} onChange={e => setDescription(e.target.value)}\n          placeholder=\"Describe tu producto...\" rows={3}\n          className=\"input-base resize-none\" />\n      </div>\n\n      {/* Precio + Categoría */}\n      <div className=\"grid grid-cols-2 gap-4\">\n        <div>\n          <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">\n            Precio <span className=\"text-red-400\">*</span>\n          </label>\n          <input type=\"number\" required min=\"0\" step=\"0.01\" value={price}\n            onChange={e => setPrice(e.target.value)}\n            placeholder=\"0\" className=\"input-base\" />\n        </div>\n        <div>\n          <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">Categoría</label>\n          <select value={categoryId} onChange={e => setCategoryId(e.target.value)} className=\"input-base\">\n            <option value=\"\">Sin categoría</option>\n            {categories.map(c => (\n              <option key={c.id} value={c.id}>{c.name}</option>\n            ))}\n          </select>\n        </div>\n      </div>\n\n      {/* Stock + Tags */}\n      <div className=\"grid grid-cols-2 gap-4\">\n        <div>\n          <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">\n            Stock <span className=\"text-gray-400 font-normal text-xs\">(opcional)</span>\n          </label>\n          <input type=\"number\" min=\"0\" value={stock} onChange={e => setStock(e.target.value)}\n            placeholder=\"Sin límite\" className=\"input-base\" />\n        </div>\n        <div>\n          <label className=\"block text-sm font-medium text-gray-700 mb-1.5\">\n            Tags <span className=\"text-gray-400 font-normal text-xs\">(separados por coma)</span>\n          </label>\n          <input type=\"text\" value={tags} onChange={e => setTags(e.target.value)}\n            placeholder=\"vegano, sin gluten...\" className=\"input-base\" />\n        </div>\n      </div>\n\n      {/* Imágenes */}\n      <div>\n        <label className=\"block text-sm font-medium text-gray-700 mb-2\">Imágenes</label>\n        <div className=\"flex flex-wrap gap-3\">\n          {images.map(url => (\n            <div key={url} className=\"relative group\">\n              <img src={url} alt=\"\" className=\"h-20 w-20 rounded-xl object-cover ring-1 ring-gray-200\" />\n              <button type=\"button\" onClick={() => removeImage(url)}\n                className=\"absolute -top-1.5 -right-1.5 flex h-5 w-5 items-center justify-center\n                           rounded-full bg-gray-900 text-white opacity-0 group-hover:opacity-100\n                           transition-opacity\">\n                <X size={10} />\n              </button>\n            </div>\n          ))}\n          <label className={`flex h-20 w-20 cursor-pointer flex-col items-center justify-center\n                            rounded-xl border-2 border-dashed border-gray-200 text-gray-400\n                            hover:border-gray-400 hover:text-gray-600 transition-colors\n                            ${uploadingImg ? 'opacity-50 cursor-not-allowed' : ''}`}>\n            {uploadingImg ? <Loader2 size={18} className=\"animate-spin\" /> : <Upload size={18} />}\n            <span className=\"text-[10px] mt-1\">{uploadingImg ? 'Subiendo...' : 'Subir'}</span>\n            <input type=\"file\" accept=\"image/*\" className=\"hidden\" onChange={uploadImage} disabled={uploadingImg} />\n          </label>\n        </div>\n      </div>\n\n      {/* Switches */}\n      <div className=\"flex items-center gap-6\">\n        <label className=\"flex items-center gap-2.5 cursor-pointer select-none\">\n          <button type=\"button\" onClick={() => setActive(v => !v)}\n            className={`relative h-5 w-9 rounded-full transition-colors ${active ? 'bg-black' : 'bg-gray-200'}`}>\n            <span className={`absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform\n                              ${active ? 'left-4' : 'left-0.5'}`} />\n          </button>\n          <span className=\"text-sm text-gray-700\">Activo</span>\n        </label>\n        <label className=\"flex items-center gap-2.5 cursor-pointer select-none\">\n          <button type=\"button\" onClick={() => setFeatured(v => !v)}\n            className={`relative h-5 w-9 rounded-full transition-colors ${featured ? 'bg-amber-500' : 'bg-gray-200'}`}>\n            <span className={`absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform\n                              ${featured ? 'left-4' : 'left-0.5'}`} />\n          </button>\n          <span className=\"text-sm text-gray-700\">Destacado</span>\n        </label>\n      </div>\n\n      {error && (\n        <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n      )}\n\n      {/* Actions */}\n      <div className=\"flex items-center gap-3 pt-2\">\n        <button type=\"submit\" disabled={loading || !name.trim() || !price}\n          className=\"flex items-center gap-2 rounded-xl bg-black px-6 py-2.5 text-sm font-medium\n                     text-white hover:bg-gray-800 transition-colors disabled:opacity-40 active:scale-[0.98]\">\n          {loading && <Loader2 size={14} className=\"animate-spin\" />}\n          {loading ? 'Guardando...' : product ? 'Guardar cambios' : 'Crear producto'}\n        </button>\n        <button type=\"button\" onClick={() => router.back()}\n          className=\"rounded-xl border border-gray-200 px-6 py-2.5 text-sm font-medium text-gray-600\n                     hover:bg-gray-50 transition-colors\">\n          Cancelar\n        </button>\n      </div>\n    </form>\n  )\n}\n"

files["app/admin/products/new/page.tsx"] = "// app/admin/products/new/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport Link from 'next/link'\nimport { ArrowLeft } from 'lucide-react'\nimport ProductForm from '../ProductForm'\n\nexport const metadata = { title: 'Nuevo producto' }\n\nexport default async function NewProductPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles').select('business_id').eq('user_id', user.id).single()\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: categories } = await supabase\n    .from('categories')\n    .select('*')\n    .eq('business_id', profile.business_id)\n    .eq('active', true)\n    .order('sort_order')\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      <div className=\"flex items-center gap-3\">\n        <Link href=\"/admin/products\"\n          className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                     text-gray-500 hover:bg-gray-100 transition-colors\">\n          <ArrowLeft size={16} />\n        </Link>\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Nuevo producto</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">Completá los datos y guardá</p>\n        </div>\n      </div>\n\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-6\">\n        <ProductForm\n          businessId={profile.business_id}\n          categories={categories ?? []}\n        />\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/products/[id]/edit/page.tsx"] = "// app/admin/products/[id]/edit/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect, notFound } from 'next/navigation'\nimport Link from 'next/link'\nimport { ArrowLeft } from 'lucide-react'\nimport ProductForm from '../../ProductForm'\n\nexport const metadata = { title: 'Editar producto' }\n\nexport default async function EditProductPage({ params }: { params: { id: string } }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles').select('business_id').eq('user_id', user.id).single()\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const [productRes, categoriesRes] = await Promise.all([\n    supabase.from('products').select('*').eq('id', params.id).eq('business_id', profile.business_id).single(),\n    supabase.from('categories').select('*').eq('business_id', profile.business_id).eq('active', true).order('sort_order'),\n  ])\n\n  if (!productRes.data) notFound()\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      <div className=\"flex items-center gap-3\">\n        <Link href=\"/admin/products\"\n          className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                     text-gray-500 hover:bg-gray-100 transition-colors\">\n          <ArrowLeft size={16} />\n        </Link>\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Editar producto</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5 truncate max-w-xs\">{productRes.data.name}</p>\n        </div>\n      </div>\n\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-6\">\n        <ProductForm\n          businessId={profile.business_id}\n          categories={categoriesRes.data ?? []}\n          product={productRes.data}\n        />\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/orders/page.tsx"] = "// app/admin/orders/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice, formatDate, orderStatusLabel, orderStatusColor } from '@/lib/utils'\nimport Link from 'next/link'\nimport { ShoppingBag } from 'lucide-react'\nimport OrderStatusFilter from './OrderStatusFilter'\nimport type { Order } from '@/types'\n\nexport const metadata = { title: 'Pedidos' }\n\nconst ALL_STATUSES = ['pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered', 'cancelled']\n\nexport default async function OrdersPage({\n  searchParams,\n}: {\n  searchParams: { status?: string }\n}) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n  const statusFilter = searchParams.status && ALL_STATUSES.includes(searchParams.status)\n    ? searchParams.status\n    : null\n\n  let query = supabase\n    .from('orders')\n    .select('*, items:order_items(product_name, quantity, unit_price)')\n    .eq('business_id', profile.business_id)\n    .order('created_at', { ascending: false })\n\n  if (statusFilter) query = query.eq('status', statusFilter)\n\n  const { data: orders } = await query\n  const list = (orders ?? []) as Order[]\n\n  // Contadores por estado\n  const counts: Record<string, number> = {}\n  ALL_STATUSES.forEach(s => {\n    counts[s] = list.filter(o => o.status === s).length\n  })\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      {/* Header */}\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Pedidos</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">{list.length} resultados</p>\n        </div>\n      </div>\n\n      {/* Filtro de estados */}\n      <OrderStatusFilter current={statusFilter} counts={counts} />\n\n      {/* Lista */}\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 p-16 text-center\">\n          <ShoppingBag size={28} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">\n            {statusFilter ? `Sin pedidos con estado \"${orderStatusLabel(statusFilter)}\"` : 'Sin pedidos todavía'}\n          </p>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {list.map(order => (\n            <Link key={order.id} href={`/admin/orders/${order.id}`}\n              className=\"group block bg-white rounded-2xl border border-gray-100\n                         hover:border-gray-300 hover:shadow-sm transition-all\">\n              <div className=\"flex items-center gap-4 px-5 py-4\">\n                {/* Número */}\n                <div className=\"shrink-0 text-center\">\n                  <p className=\"text-xs font-mono text-gray-400\">#{String(order.order_number).padStart(4, '0')}</p>\n                  <span className={`badge ${orderStatusColor(order.status)} mt-1`}>\n                    {orderStatusLabel(order.status)}\n                  </span>\n                </div>\n\n                {/* Cliente */}\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-semibold text-gray-900 truncate\">{order.customer_name}</p>\n                  <p className=\"text-xs text-gray-400 mt-0.5\">\n                    {order.customer_phone ?? '—'} · {order.delivery_type === 'delivery' ? '🛵 Delivery' : '🏃 Retiro'}\n                  </p>\n                  {/* Items preview */}\n                  {order.items && order.items.length > 0 && (\n                    <p className=\"text-xs text-gray-400 mt-1 truncate\">\n                      {order.items.map(i => `${i.quantity}x ${i.product_name}`).join(' · ')}\n                    </p>\n                  )}\n                </div>\n\n                {/* Total + fecha */}\n                <div className=\"shrink-0 text-right\">\n                  <p className=\"text-sm font-bold text-gray-900\">{formatPrice(order.total, currency)}</p>\n                  <p className=\"text-xs text-gray-400 mt-0.5\">{formatDate(order.created_at)}</p>\n                </div>\n              </div>\n            </Link>\n          ))}\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/orders/OrderStatusFilter.tsx"] = "// app/admin/orders/OrderStatusFilter.tsx\n'use client'\nimport { useRouter, usePathname } from 'next/navigation'\nimport { orderStatusLabel } from '@/lib/utils'\nimport { cn } from '@/lib/utils'\n\nconst STATUSES = ['pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered', 'cancelled']\n\nexport default function OrderStatusFilter({\n  current,\n  counts,\n}: {\n  current: string | null\n  counts: Record<string, number>\n}) {\n  const router = useRouter()\n  const pathname = usePathname()\n\n  function filter(status: string | null) {\n    if (status) router.push(`${pathname}?status=${status}`)\n    else router.push(pathname)\n  }\n\n  return (\n    <div className=\"flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide\">\n      <button\n        onClick={() => filter(null)}\n        className={cn(\n          'shrink-0 rounded-xl px-3.5 py-1.5 text-xs font-medium transition-all',\n          !current ? 'bg-gray-900 text-white' : 'bg-white border border-gray-200 text-gray-500 hover:bg-gray-50'\n        )}\n      >\n        Todos\n      </button>\n      {STATUSES.map(s => (\n        <button\n          key={s}\n          onClick={() => filter(s)}\n          className={cn(\n            'shrink-0 flex items-center gap-1.5 rounded-xl px-3.5 py-1.5 text-xs font-medium transition-all',\n            current === s ? 'bg-gray-900 text-white' : 'bg-white border border-gray-200 text-gray-500 hover:bg-gray-50'\n          )}\n        >\n          {orderStatusLabel(s)}\n          {counts[s] > 0 && (\n            <span className={cn(\n              'flex h-4 w-4 items-center justify-center rounded-full text-[10px]',\n              current === s ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-600'\n            )}>\n              {counts[s]}\n            </span>\n          )}\n        </button>\n      ))}\n    </div>\n  )\n}\n"

files["app/admin/orders/[id]/page.tsx"] = "// app/admin/orders/[id]/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect, notFound } from 'next/navigation'\nimport { formatPrice, formatDate, orderStatusLabel, orderStatusColor } from '@/lib/utils'\nimport Link from 'next/link'\nimport { ArrowLeft, MessageCircle, MapPin, Phone, ShoppingBag, Clock } from 'lucide-react'\nimport OrderStatusUpdater from './OrderStatusUpdater'\nimport type { Order, OrderItem } from '@/types'\n\nexport const metadata = { title: 'Detalle pedido' }\n\nexport default async function OrderDetailPage({ params }: { params: { id: string } }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency, whatsapp)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: order } = await supabase\n    .from('orders')\n    .select('*, items:order_items(*)')\n    .eq('id', params.id)\n    .eq('business_id', profile.business_id)\n    .single()\n\n  if (!order) notFound()\n\n  const biz = profile.business as { currency: string; whatsapp?: string } | null\n  const currency = biz?.currency ?? 'UYU'\n  const o = order as Order & { items: OrderItem[] }\n\n  // Construir link de WhatsApp para contactar al cliente\n  const waLink = o.customer_phone\n    ? `https://wa.me/${o.customer_phone.replace(/\\D/g, '')}?text=${encodeURIComponent(\n        `Hola ${o.customer_name}! Te escribimos por tu pedido #${String(o.order_number).padStart(4, '0')} de FYP.STUDIO.`\n      )}`\n    : null\n\n  return (\n    <div className=\"space-y-6 animate-fade-in max-w-2xl\">\n      {/* Header */}\n      <div className=\"flex items-center gap-3\">\n        <Link href=\"/admin/orders\"\n          className=\"flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200\n                     text-gray-500 hover:bg-gray-100 transition-colors\">\n          <ArrowLeft size={16} />\n        </Link>\n        <div className=\"flex-1\">\n          <div className=\"flex items-center gap-3\">\n            <h1 className=\"text-2xl font-semibold tracking-tight\">\n              #{String(o.order_number).padStart(4, '0')}\n            </h1>\n            <span className={`badge ${orderStatusColor(o.status)}`}>\n              {orderStatusLabel(o.status)}\n            </span>\n          </div>\n          <p className=\"text-sm text-gray-400 mt-0.5 flex items-center gap-1\">\n            <Clock size={12} /> {formatDate(o.created_at)}\n          </p>\n        </div>\n      </div>\n\n      {/* Cambiar estado */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n        <p className=\"text-sm font-medium text-gray-700 mb-3\">Estado del pedido</p>\n        <OrderStatusUpdater orderId={o.id} currentStatus={o.status} />\n      </div>\n\n      {/* Cliente */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n        <p className=\"text-sm font-medium text-gray-700 mb-4\">Cliente</p>\n        <div className=\"space-y-2.5\">\n          <div className=\"flex items-center gap-2.5 text-sm text-gray-600\">\n            <div className=\"h-7 w-7 rounded-lg bg-gray-100 flex items-center justify-center shrink-0\">\n              <span className=\"text-xs font-semibold text-gray-500\">\n                {o.customer_name.slice(0, 1).toUpperCase()}\n              </span>\n            </div>\n            <span className=\"font-medium text-gray-900\">{o.customer_name}</span>\n          </div>\n          {o.customer_phone && (\n            <div className=\"flex items-center gap-2.5 text-sm text-gray-600\">\n              <div className=\"h-7 w-7 rounded-lg bg-gray-100 flex items-center justify-center shrink-0\">\n                <Phone size={12} className=\"text-gray-400\" />\n              </div>\n              <span>{o.customer_phone}</span>\n            </div>\n          )}\n          {o.customer_address && (\n            <div className=\"flex items-start gap-2.5 text-sm text-gray-600\">\n              <div className=\"h-7 w-7 rounded-lg bg-gray-100 flex items-center justify-center shrink-0 mt-0.5\">\n                <MapPin size={12} className=\"text-gray-400\" />\n              </div>\n              <span>{o.customer_address}</span>\n            </div>\n          )}\n        </div>\n\n        <div className=\"mt-4 flex items-center gap-2\">\n          <span className={`badge ${o.delivery_type === 'delivery' ? 'bg-blue-50 text-blue-700' : 'bg-purple-50 text-purple-700'}`}>\n            {o.delivery_type === 'delivery' ? '🛵 Delivery' : '🏃 Retiro en local'}\n          </span>\n          {waLink && (\n            <a href={waLink} target=\"_blank\"\n              className=\"flex items-center gap-1.5 rounded-xl bg-green-500 px-3 py-1.5 text-xs font-medium\n                         text-white hover:bg-green-600 transition-colors\">\n              <MessageCircle size={12} />\n              WhatsApp\n            </a>\n          )}\n        </div>\n      </div>\n\n      {/* Productos */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n        <p className=\"text-sm font-medium text-gray-700 mb-4\">Productos</p>\n        <div className=\"space-y-3\">\n          {o.items?.map(item => (\n            <div key={item.id} className=\"flex items-center justify-between\">\n              <div className=\"flex items-center gap-3\">\n                <div className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-gray-100\">\n                  <ShoppingBag size={12} className=\"text-gray-400\" />\n                </div>\n                <div>\n                  <p className=\"text-sm font-medium text-gray-900\">{item.product_name}</p>\n                  <p className=\"text-xs text-gray-400\">{formatPrice(item.unit_price, currency)} c/u</p>\n                </div>\n              </div>\n              <div className=\"text-right\">\n                <p className=\"text-sm font-semibold text-gray-900\">\n                  {formatPrice(item.unit_price * item.quantity, currency)}\n                </p>\n                <p className=\"text-xs text-gray-400\">×{item.quantity}</p>\n              </div>\n            </div>\n          ))}\n        </div>\n\n        <div className=\"mt-4 pt-4 border-t border-gray-100\">\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-sm font-semibold text-gray-900\">Total</p>\n            <p className=\"text-lg font-bold text-gray-900\">{formatPrice(o.total, currency)}</p>\n          </div>\n          {!o.confirmed_sale && (\n            <p className=\"text-xs text-gray-400 mt-1\">\n              ⚠️ No contabilizado como venta real (aún no confirmado)\n            </p>\n          )}\n          {o.confirmed_sale && (\n            <p className=\"text-xs text-green-600 mt-1\">✓ Venta confirmada</p>\n          )}\n        </div>\n      </div>\n\n      {/* Comentario */}\n      {o.comment && (\n        <div className=\"bg-amber-50 rounded-2xl border border-amber-100 px-5 py-4\">\n          <p className=\"text-xs font-medium text-amber-700 mb-1\">Comentario del cliente</p>\n          <p className=\"text-sm text-amber-900\">{o.comment}</p>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/orders/[id]/OrderStatusUpdater.tsx"] = "// app/admin/orders/[id]/OrderStatusUpdater.tsx\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { orderStatusLabel, orderStatusColor, cn } from '@/lib/utils'\nimport { Check, Loader2 } from 'lucide-react'\n\nconst STATUSES = [\n  'pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered', 'cancelled'\n] as const\n\ntype Status = typeof STATUSES[number]\n\n// Flujo visual: qué estados son \"progreso\" vs \"final\"\nconst STATUS_ORDER = ['pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered']\n\nexport default function OrderStatusUpdater({\n  orderId,\n  currentStatus,\n}: {\n  orderId: string\n  currentStatus: string\n}) {\n  const router = useRouter()\n  const supabase = createClient()\n  const [loading, setLoading] = useState<string | null>(null)\n  const [selected, setSelected] = useState(currentStatus)\n\n  async function updateStatus(status: Status) {\n    if (status === selected) return\n    setLoading(status)\n    await supabase.from('orders').update({ status }).eq('id', orderId)\n    setSelected(status)\n    router.refresh()\n    setLoading(null)\n  }\n\n  const currentIdx = STATUS_ORDER.indexOf(selected)\n\n  return (\n    <div className=\"space-y-4\">\n      {/* Barra de progreso (solo para estados no cancelados) */}\n      {selected !== 'cancelled' && (\n        <div className=\"flex items-center gap-1.5\">\n          {STATUS_ORDER.map((s, i) => (\n            <div key={s} className=\"flex-1 flex items-center\">\n              <div className={cn(\n                'h-1.5 w-full rounded-full transition-all',\n                i <= currentIdx ? 'bg-gray-900' : 'bg-gray-100'\n              )} />\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Botones de estado */}\n      <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-2\">\n        {STATUSES.map(s => (\n          <button\n            key={s}\n            onClick={() => updateStatus(s)}\n            disabled={loading !== null}\n            className={cn(\n              'flex items-center justify-center gap-1.5 rounded-xl px-3 py-2 text-xs font-medium transition-all',\n              selected === s\n                ? 'ring-2 ring-gray-900 ring-offset-1 bg-white shadow-sm'\n                : 'bg-gray-50 hover:bg-gray-100 text-gray-600',\n              s === 'cancelled' && selected !== 'cancelled' && 'hover:bg-red-50 hover:text-red-600'\n            )}\n          >\n            {loading === s ? (\n              <Loader2 size={11} className=\"animate-spin\" />\n            ) : selected === s ? (\n              <Check size={11} />\n            ) : null}\n            <span className={selected === s ? orderStatusColor(s).split(' ')[1] : ''}>\n              {orderStatusLabel(s)}\n            </span>\n          </button>\n        ))}\n      </div>\n    </div>\n  )\n}\n"

files["components/admin/AdminSidebar.tsx"] = "// components/admin/AdminSidebar.tsx\n'use client'\nimport Link from 'next/link'\nimport { usePathname, useRouter } from 'next/navigation'\nimport {\n  LayoutDashboard, ShoppingBag, Package, Users,\n  Settings, Sparkles, LogOut, Tag, ExternalLink, ChevronRight,\n} from 'lucide-react'\nimport { createClient } from '@/lib/supabase/client'\nimport { cn } from '@/lib/utils'\nimport type { Business } from '@/types'\n\nconst NAV = [\n  { href: '/admin',            label: 'Dashboard',      icon: LayoutDashboard, exact: true },\n  { href: '/admin/orders',     label: 'Pedidos',        icon: ShoppingBag },\n  { href: '/admin/products',   label: 'Productos',      icon: Package },\n  { href: '/admin/categories', label: 'Categorías',     icon: Tag },\n  { href: '/admin/customers',  label: 'Clientes',       icon: Users },\n  { href: '/admin/ai',         label: 'IA',             icon: Sparkles },\n  { href: '/admin/settings',   label: 'Configuración',  icon: Settings },\n]\n\nexport default function AdminSidebar({ business, userEmail }: { business: Business | null; userEmail: string }) {\n  const pathname = usePathname()\n  const router = useRouter()\n  const supabase = createClient()\n\n  async function handleLogout() {\n    await supabase.auth.signOut()\n    router.push('/auth/login')\n    router.refresh()\n  }\n\n  const initials = business?.name?.split(' ').slice(0, 2).map(w => w[0]).join('').toUpperCase() ?? 'FY'\n\n  return (\n    <aside className=\"w-[220px] bg-white border-r border-gray-100 flex flex-col h-full shrink-0\">\n      {/* Branding */}\n      <div className=\"px-4 py-5 border-b border-gray-100\">\n        <div className=\"flex items-center gap-3\">\n          {business?.logo_url ? (\n            <img src={business.logo_url} alt={business.name}\n              className=\"h-8 w-8 rounded-lg object-cover ring-1 ring-gray-200\" />\n          ) : (\n            <div className=\"h-8 w-8 rounded-lg bg-gray-900 flex items-center justify-center\n                            text-white text-[11px] font-bold tracking-wide shrink-0\">\n              {initials}\n            </div>\n          )}\n          <div className=\"min-w-0\">\n            <p className=\"text-sm font-semibold text-gray-900 truncate leading-tight\">\n              {business?.name ?? 'Mi comercio'}\n            </p>\n            <div className=\"flex items-center gap-1 mt-0.5\">\n              <span className=\"h-1.5 w-1.5 rounded-full bg-green-400 shrink-0\" />\n              <p className=\"text-[11px] text-gray-400 capitalize\">{business?.plan ?? 'basic'}</p>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* Nav */}\n      <nav className=\"flex-1 p-2.5 space-y-0.5 overflow-y-auto\">\n        {NAV.map(({ href, label, icon: Icon, exact }) => {\n          const isActive = exact ? pathname === href : pathname.startsWith(href)\n          return (\n            <Link key={href} href={href}\n              className={cn(\n                'group flex items-center justify-between rounded-xl px-3 py-2 text-sm transition-all',\n                isActive\n                  ? 'bg-gray-100 text-gray-900 font-medium'\n                  : 'text-gray-500 hover:bg-gray-50 hover:text-gray-800'\n              )}>\n              <div className=\"flex items-center gap-2.5\">\n                <Icon size={15} className={isActive ? 'text-gray-800' : 'text-gray-400'} />\n                {label}\n              </div>\n              {isActive && <ChevronRight size={12} className=\"text-gray-400\" />}\n            </Link>\n          )\n        })}\n      </nav>\n\n      {/* Footer */}\n      <div className=\"p-2.5 border-t border-gray-100 space-y-0.5\">\n        {business?.slug && (\n          <Link href={`/store/${business.slug}`} target=\"_blank\"\n            className=\"flex items-center gap-2.5 rounded-xl px-3 py-2 text-sm text-gray-400\n                       hover:bg-gray-50 hover:text-gray-700 transition-all\">\n            <ExternalLink size={14} />\n            <span>Ver tienda</span>\n          </Link>\n        )}\n        <button onClick={handleLogout}\n          className=\"w-full flex items-center gap-2.5 rounded-xl px-3 py-2 text-sm text-gray-400\n                     hover:bg-red-50 hover:text-red-600 transition-all\">\n          <LogOut size={14} />\n          <span>Salir</span>\n        </button>\n        <p className=\"px-3 pt-1 text-[11px] text-gray-300 truncate\">{userEmail}</p>\n      </div>\n    </aside>\n  )\n}\n"

let created = 0
for (const [filePath, content] of Object.entries(files)) {
  const dir = path.dirname(filePath)
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true })
  fs.writeFileSync(filePath, content, 'utf8')
  console.log('  ✅ ' + filePath)
  created++
}
console.log('\n✨ ' + created + ' archivos del panel admin listos.')
console.log('\n📋 PRÓXIMO PASO: npm run dev y abrí /admin')
